<span class="line"><span style="color:#ABB2BF;">    CreateDate </span><span style="color:#C678DD;">DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#56B6C2;"> SYSDATETIME</span><span style="color:#ABB2BF;">()</span></span>
