<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> NONCLUSTERED</span><span style="color:#C678DD;"> INDEX</span><span style="color:#ABB2BF;"> IX_Orders_Active</span></span>
